class Solution {
public:
    string longestWord(vector<string>& words) {
        sort(words.begin(), words.end());
        unordered_set<string> valid = {""};
        string longest = "";
        for (const string& w : words) {
            if (valid.count(w.substr(0, w.size() - 1))) {
                valid.insert(w);
                if (w.size() > longest.size()) {
                    longest = w;
                }
            }
        }
        return longest;
    }
};

class Solution {
    public String longestWord(String[] words) {
        Arrays.sort(words);
        Set<String> valid = new HashSet<>();
        valid.add("");
        String longest = "";
        for (String w : words) {
            if (valid.contains(w.substring(0, w.length() - 1))) {
                valid.add(w);
                if (w.length() > longest.length()) {
                    longest = w;
                }
            }
        }
        return longest;
    }
}

var longestWord = function(words) {
    words.sort();
    const valid = new Set([""]);
    let longest = "";
    for (const w of words) {
        if (valid.has(w.slice(0, w.length - 1))) {
            valid.add(w);
            if (w.length > longest.length) {
                longest = w;
            }
        }
    }
